  "BFS": PracticeExercise("from collections import deque\ng=[[1,2],[0,3],[0],[1]]; d=[-1]*4; d[0]=0; q=deque([0])\nwhile q:\n    u=q.popleft()\n    for v in g[u]:\n        if d[v]<0: d[v]=d[u]+1; q.append(v)\nprint(d)", "BFS-д queue-ийн эхнээс орой авах method-ийг бич.", "from collections import deque\ng=[[1,2],[0,3],[0],[1]]; d=[-1]*4; d[0]=0; q=deque([0])\nwhile q:\n    u=q.", "()\n    for v in g[u]:\n        if d[v]<0: d[v]=d[u]+1; q.append(v)\nprint(d)", "popleft"),
  "DFS": PracticeExercise("g=[[1,2],[0],[0]]; stack=[0]; seen=set()\nwhile stack:\n    u=stack.pop()\n    if u in seen: continue\n    seen.add(u); stack.extend(g[u])\nprint(sorted(seen))", "DFS-д stack-ийн төгсгөлөөс орой авах method-ийг бич.", "g=[[1,2],[0],[0]]; stack=[0]; seen=set()\nwhile stack:\n    u=stack.", "()\n    if u in seen: continue\n    seen.add(u); stack.extend(g[u])\nprint(sorted(seen))", "pop"),
  "Холбоост бүрэлдэхүүн": PracticeExercise("g=[[1],[0],[]]; seen=set(); count=0\nfor u in range(3):\n    if u in seen: continue\n    count+=1; stack=[u]\n    while stack:\n        v=stack.pop()\n        if v not in seen: seen.add(v); stack.extend(g[v])\nprint(count)", "Шинэ холбоост бүрэлдэхүүн олдсон үед тоолуурыг нэгээр нэмэх мөрийг бич.", "g=[[1],[0],[]]; seen=set(); count=0\nfor u in range(3):\n    if u in seen: continue\n    ", "; stack=[u]\n    while stack:\n        v=stack.pop()\n        if v not in seen: seen.add(v); stack.extend(g[v])\nprint(count)", "count+=1"),
  "Топологийн эрэмбэ": PracticeExercise("g=[[1,2],[2],[]]; deg=[0,1,2]; q=[0]; order=[]\nwhile q:\n    u=q.pop(); order.append(u)\n    for v in g[u]:\n        deg[v]-=1\n        if deg[v]==0: q.append(v)\nprint(order)", "Орох ирмэг үлдээгүй оройг queue-д нэмэх нөхцөлийг бич.", "g=[[1,2],[2],[]]; deg=[0,1,2]; q=[0]; order=[]\nwhile q:\n    u=q.pop(); order.append(u)\n    for v in g[u]:\n        deg[v]-=1\n        if ", ": q.append(v)\nprint(order)", "deg[v]==0"),
  "Цикл илрүүлэх": PracticeExercise("g=[[1],[0]]; deg=[1,1]; ready=[i for i,d in enumerate(deg) if d==0]; print(not ready)", "Орох ирмэггүй оройг сонгох нөхцөлийг бич.", "g=[[1],[0]]; deg=[1,1]; ready=[i for i,d in enumerate(deg) if ", "]; print(not ready)", "d==0"),
  "Dijkstra": PracticeExercise("import heapq\ng=[[(1,4),(2,1)],[],[(1,2)]]; d=[0,float('inf'),float('inf')]; q=[(0,0)]\nwhile q:\n    du,u=heapq.heappop(q)\n    if du!=d[u]: continue\n    for v,w in g[u]:\n        if du+w<d[v]: d[v]=du+w; heapq.heappush(q,(d[v],v))\nprint(d)", "Шинэ зам одоогийн зайнаас богино байх нөхцөлийг бич.", "import heapq\ng=[[(1,4),(2,1)],[],[(1,2)]]; d=[0,float('inf'),float('inf')]; q=[(0,0)]\nwhile q:\n    du,u=heapq.heappop(q)\n    if du!=d[u]: continue\n    for v,w in g[u]:\n        if ", ": d[v]=du+w; heapq.heappush(q,(d[v],v))\nprint(d)", "du+w<d[v]"),
  "Bellman–Ford": PracticeExercise("edges=[(0,1,4),(1,2,-2),(0,2,5)]; d=[0,float('inf'),float('inf')]\nfor _ in range(2):\n    for u,v,w in edges: d[v]=min(d[v],d[u]+w)\nprint(d)", "Одоогийн зай ба u-ээр дамжих шинэ зайны багыг сонгох илэрхийллийг бич.", "edges=[(0,1,4),(1,2,-2),(0,2,5)]; d=[0,float('inf'),float('inf')]\nfor _ in range(2):\n    for u,v,w in edges: d[v]=", "\nprint(d)", "min(d[v],d[u]+w)"),
  "Floyd–Warshall": PracticeExercise("inf=float('inf'); d=[[0,3,inf],[inf,0,2],[inf,inf,0]]\nfor k in range(3):\n    for i in range(3):\n        for j in range(3): d[i][j]=min(d[i][j],d[i][k]+d[k][j])\nprint(d[0][2])", "i-ээс k-ээр дамжин j хүрэх замын уртыг бич.", "inf=float('inf'); d=[[0,3,inf],[inf,0,2],[inf,inf,0]]\nfor k in range(3):\n    for i in range(3):\n        for j in range(3): d[i][j]=min(d[i][j],", ")\nprint(d[0][2])", "d[i][k]+d[k][j]"),
  "Disjoint set union": PracticeExercise("p=list(range(4))\ndef find(x):\n    while p[x]!=x: p[x]=p[p[x]]; x=p[x]\n    return x\np[find(1)]=find(0); print(find(1)==find(0))", "Path compression хийхдээ x-ийн өвөө зангилааг авах илэрхийллийг бич.", "p=list(range(4))\ndef find(x):\n    while p[x]!=x: p[x]=", "; x=p[x]\n    return x\np[find(1)]=find(0); print(find(1)==find(0))", "p[p[x]]"),
  "Kruskal ба MST": PracticeExercise("edges=[(3,0,1),(1,1,2),(2,0,2)]; p=list(range(3))\ndef f(x):\n    while p[x]!=x: x=p[x]\n    return x\nt=0\nfor w,u,v in sorted(edges):\n    if f(u)!=f(v): p[f(u)]=f(v); t+=w\nprint(t)", "Ирмэгийн хоёр орой өөр бүрэлдэхүүнд байх нөхцөлийг бич.", "edges=[(3,0,1),(1,1,2),(2,0,2)]; p=list(range(3))\ndef f(x):\n    while p[x]!=x: x=p[x]\n    return x\nt=0\nfor w,u,v in sorted(edges):\n    if ", ": p[f(u)]=f(v); t+=w\nprint(t)", "f(u)!=f(v)"),
