  "Longest common subsequence": PracticeExercise("a,b='abc','ac'; d=[[0]*3 for _ in range(4)]\nfor i,x in enumerate(a,1):\n    for j,y in enumerate(b,1): d[i][j]=d[i-1][j-1]+1 if x==y else max(d[i-1][j],d[i][j-1])\nprint(d[-1][-1])", "Хоёр тэмдэгт тэнцүү үед LCS-ийн шинэ уртыг бич.", "a,b='abc','ac'; d=[[0]*3 for _ in range(4)]\nfor i,x in enumerate(a,1):\n    for j,y in enumerate(b,1): d[i][j]=", " if x==y else max(d[i-1][j],d[i][j-1])\nprint(d[-1][-1])", "d[i-1][j-1]+1"),
  "Grid DP": PracticeExercise("d=[[1]*3 for _ in range(3)]\nfor i in range(1,3):\n    for j in range(1,3): d[i][j]=d[i-1][j]+d[i][j-1]\nprint(d[2][2])", "Дээд болон зүүн нүднээс ирэх замын тоог нэмэх илэрхийллийг бич.", "d=[[1]*3 for _ in range(3)]\nfor i in range(1,3):\n    for j in range(1,3): d[i][j]=", "\nprint(d[2][2])", "d[i-1][j]+d[i][j-1]"),
  "DP шийдэл сэргээх": PracticeExercise("d=[0,1,2,1]; prev=[-1,0,1,0]; x=3; route=[]\nwhile x!=-1: route.append(x); x=prev[x]\nprint(route[::-1])", "DP шийдэл сэргээхдээ өмнөх төлөвийг авах илэрхийллийг бич.", "d=[0,1,2,1]; prev=[-1,0,1,0]; x=3; route=[]\nwhile x!=-1: route.append(x); x=", "\nprint(route[::-1])", "prev[x]"),
